def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                        (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append((color, cells))

    # Find the L component by its two long perpendicular arms.
    candidates = []
    for i, (color, cells) in enumerate(comps):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        s = set(cells)
        for cr, cc in ((r0,c0), (r0,c1), (r1,c0), (r1,c1)):
            horizontal = sum((cr, c) in s for c in range(c0, c1+1))
            vertical = sum((r, cc) in s for r in range(r0, r1+1))
            if horizontal >= 3 and vertical >= 3:
                if horizontal >= .65*(c1-c0+1) and vertical >= .65*(r1-r0+1):
                    candidates.append((horizontal+vertical, len(cells), i, cr, cc))

    if not candidates:
        return [row[:] for row in grid]

    _, _, li, cr, cc = max(candidates)
    lcolor = comps[li][0]
    l_cells = comps[li][1]
    r0 = min(r for r, c in l_cells)
    c0 = min(c for r, c in l_cells)
    # The quadrant opposite the two arms.
    row_sign = 1 if cr == r0 else -1
    col_sign = 1 if cc == c0 else -1

    targets = []
    for i, (color, cells) in enumerate(comps):
        if i == li:
            continue
        mr = sum(r for r, c in cells) / len(cells)
        mc = sum(c for r, c in cells) / len(cells)
        if (mr - cr) * row_sign > 0 and (mc - cc) * col_sign > 0:
            targets.append(cells)

    out = [row[:] for row in grid]
    for cells in targets:
        for r, c in cells:
            out[r][c] = lcolor
    return out
